#!/usr/bin/env python3
from __future__ import annotations
import json, math
from pathlib import Path
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.calibration import calibration_curve
from sklearn.decomposition import PCA
from sklearn.metrics import roc_curve, auc
from sklearn.preprocessing import label_binarize

OUT=Path("benchmark_output")
FIG=OUT/"figures";FIG.mkdir(parents=True,exist_ok=True)
plt.rcParams.update({"font.size":9,"axes.titlesize":10,"axes.labelsize":9,"legend.fontsize":8,"figure.dpi":180,"savefig.dpi":300})
CL=list("ABCDE")
NAMES={"A":"Correct","B":"Elbow forward","C":"Incomplete lift","D":"Incomplete lower","E":"Trunk thrust"}

def save(name):
 plt.tight_layout();plt.savefig(FIG/name,bbox_inches="tight");plt.close()

def ci95(x):
 x=np.asarray(x,float);return 1.96*x.std(ddof=1)/math.sqrt(len(x)) if len(x)>1 else 0

def pct(x):return 100*float(x)
def fmt(x,n=3):return f"{float(x):.{n}f}"
def esc(s):return str(s).replace("_","\\_").replace("%","\\%")

def main():
 fold=pd.read_csv(OUT/"fold_metrics.csv");sm=pd.read_csv(OUT/"metrics_summary.csv");cm=pd.read_csv(OUT/"confusion_normalized.csv",index_col=0);cc=pd.read_csv(OUT/"class_metrics.csv");pred=pd.read_csv(OUT/"predictions.csv");manifest=json.loads((OUT/"experiment_manifest.json").read_text());hier=json.loads((OUT/"hierarchical_metrics.json").read_text());res=json.loads((OUT/"RESULTS.json").read_text());P=np.load(OUT/"probabilities.npy");Y=np.load(OUT/"labels.npy");E=np.load(OUT/"embeddings.npy");SID=np.load(OUT/"subject_ids.npy",allow_pickle=True)
 order=["Arm-only ExtraTrees","Forearm-only ExtraTrees","Early-fusion ExtraTrees","Physics-guided ExtraTrees","KineTwin-Former"]
 short={"Arm-only ExtraTrees":"Arm only","Forearm-only ExtraTrees":"Forearm only","Early-fusion ExtraTrees":"Early fusion","Physics-guided ExtraTrees":"Physics-guided","KineTwin-Former":"KineTwin-Former"}
 # 1 model comparison
 d=sm.set_index("model").loc[order];x=np.arange(len(order));w=.36
 plt.figure(figsize=(7.2,3.8));plt.bar(x-w/2,100*d.macro_f1_mean,w,yerr=100*d.macro_f1_std,capsize=3,label="Macro-F1");plt.bar(x+w/2,100*d.balanced_accuracy_mean,w,yerr=100*d.balanced_accuracy_std,capsize=3,label="Balanced accuracy");plt.xticks(x,[short[z] for z in order],rotation=15,ha="right");plt.ylabel("Performance (%)");plt.ylim(0,100);plt.grid(axis="y",alpha=.25);plt.legend(ncol=2);plt.title("Subject-independent model comparison (mean $\\pm$ SD across LOSO folds)");save("model_comparison.pdf")
 # 2 subject generalization
 piv=fold.pivot(index="subject_id",columns="model",values="macro_f1").sort_index();
 plt.figure(figsize=(7.2,3.8))
 for name in ["Physics-guided ExtraTrees","KineTwin-Former"]:plt.plot(piv.index,100*piv[name],marker="o",linewidth=1.7,label=short[name])
 plt.ylabel("Macro-F1 (%)");plt.xlabel("Held-out subject");plt.ylim(0,100);plt.grid(alpha=.25);plt.legend();plt.title("Leave-one-subject-out generalization");save("subject_generalization.pdf")
 # 3 confusion
 plt.figure(figsize=(5.2,4.4));im=plt.imshow(100*cm.values,vmin=0,vmax=100,aspect="auto");plt.colorbar(im,label="Row-normalized rate (%)");plt.xticks(range(5),CL);plt.yticks(range(5),CL);plt.xlabel("Predicted class");plt.ylabel("True class");plt.title("KineTwin-Former confusion matrix")
 for i in range(5):
  for j in range(5):plt.text(j,i,f"{100*cm.iloc[i,j]:.1f}",ha="center",va="center",fontsize=8)
 save("confusion_matrix.pdf")
 # 4 ROC
 yb=label_binarize(Y,classes=np.arange(5));plt.figure(figsize=(5.5,4.4))
 for j,c in enumerate(CL):
  fpr,tpr,_=roc_curve(yb[:,j],P[:,j]);plt.plot(fpr,tpr,label=f"{c}: AUC={auc(fpr,tpr):.3f}")
 plt.plot([0,1],[0,1],"--",linewidth=1);plt.xlabel("False-positive rate");plt.ylabel("True-positive rate");plt.grid(alpha=.25);plt.legend();plt.title("One-vs-rest ROC curves");save("roc_curves.pdf")
 # 5 PCA embedding
 z=PCA(n_components=2,random_state=0).fit_transform(E);plt.figure(figsize=(6.2,4.8))
 for j,c in enumerate(CL):
  m=Y==j;plt.scatter(z[m,0],z[m,1],s=18,alpha=.65,label=f"{c}: {NAMES[c]}")
 plt.xlabel("PC1");plt.ylabel("PC2");plt.grid(alpha=.2);plt.legend(markerscale=1.2);plt.title("Learned digital-twin embedding space");save("embedding_pca.pdf")
 # 6 reliability
 conf=P.max(1);correct=(P.argmax(1)==Y).astype(int);pt,pp=calibration_curve(correct,conf,n_bins=10,strategy="quantile");plt.figure(figsize=(5.2,4.2));plt.plot(pp,pt,marker="o",label="KineTwin-Former");plt.plot([0,1],[0,1],"--",label="Perfect calibration");plt.xlabel("Mean confidence");plt.ylabel("Empirical accuracy");plt.grid(alpha=.25);plt.legend();plt.title(f"Reliability diagram (ECE={manifest['statistics']['ece']:.3f})");save("reliability.pdf")
 # 7 classwise
 x=np.arange(5);w=.25;plt.figure(figsize=(6.8,3.9));plt.bar(x-w,100*cc.precision,w,label="Precision");plt.bar(x,100*cc.recall,w,label="Recall");plt.bar(x+w,100*cc.f1,w,label="F1");plt.xticks(x,[f"{c}\n{NAMES[c]}" for c in CL]);plt.ylabel("Score (%)");plt.ylim(0,100);plt.grid(axis="y",alpha=.25);plt.legend(ncol=3);plt.title("Class-wise performance");save("classwise_metrics.pdf")
 # 8 hierarchical task
 labels=["5-class quality","Correct vs incorrect","Biomechanical taxonomy"];vals=[hier["five"]["macro_f1"],hier["binary"]["macro_f1"],hier["taxonomy"]["macro_f1"]];plt.figure(figsize=(6.3,3.7));bars=plt.bar(labels,100*np.array(vals));plt.ylabel("Macro-F1 (%)");plt.ylim(0,100);plt.xticks(rotation=12,ha="right");plt.grid(axis="y",alpha=.25);plt.title("Hierarchical rehabilitation interpretation")
 for b,v in zip(bars,vals):plt.text(b.get_x()+b.get_width()/2,100*v+1,f"{100*v:.1f}",ha="center")
 save("hierarchical_tasks.pdf")
 # 9 error-energy landscape
 pred["correct"]=(pred.true_label==pred.predicted_label).astype(int);plt.figure(figsize=(5.5,4.4));
 for val,label in [(1,"Correct prediction"),(0,"Error")]:
  m=pred.correct==val;plt.scatter(pred.loc[m,"rel_gyro_energy"],pred.loc[m,"rel_accel_energy"],s=18,alpha=.6,label=label)
 plt.xscale("log");plt.yscale("log");plt.xlabel("Relative gyro energy");plt.ylabel("Relative acceleration energy");plt.grid(alpha=.2);plt.legend();plt.title("Prediction errors in the cross-segment energy space");save("error_energy.pdf")
 # 10 dashboard
 fig,axs=plt.subplots(2,2,figsize=(8.2,6.2));axs[0,0].bar([short[z] for z in order],100*d.macro_f1_mean);axs[0,0].tick_params(axis="x",rotation=20);axs[0,0].set_ylim(0,100);axs[0,0].set_title("Macro-F1 by model");axs[0,0].grid(axis="y",alpha=.2)
 axs[0,1].imshow(100*cm.values,vmin=0,vmax=100);axs[0,1].set_xticks(range(5),CL);axs[0,1].set_yticks(range(5),CL);axs[0,1].set_title("Normalized confusion")
 for name in ["Physics-guided ExtraTrees","KineTwin-Former"]:axs[1,0].plot(piv.index,100*piv[name],marker="o",label=short[name]);axs[1,0].set_ylim(0,100);axs[1,0].tick_params(axis="x",rotation=20);axs[1,0].legend();axs[1,0].set_title("Held-out subjects");axs[1,0].grid(alpha=.2)
 axs[1,1].plot(pp,pt,marker="o");axs[1,1].plot([0,1],[0,1],"--");axs[1,1].set_title("Calibration");axs[1,1].set_xlabel("Confidence");axs[1,1].set_ylabel("Accuracy");axs[1,1].grid(alpha=.2);fig.tight_layout();fig.savefig(FIG/"results_dashboard.pdf",bbox_inches="tight");plt.close(fig)
 # tables
 table_rows=[]
 for name in order:
  r=sm[sm.model==name].iloc[0];table_rows.append(f"{esc(short[name])} & {100*r.accuracy_mean:.2f}$\\pm${100*r.accuracy_std:.2f} & {100*r.balanced_accuracy_mean:.2f}$\\pm${100*r.balanced_accuracy_std:.2f} & {100*r.macro_f1_mean:.2f}$\\pm${100*r.macro_f1_std:.2f} & {100*r.macro_auc_ovr_mean:.2f}$\\pm${100*r.macro_auc_ovr_std:.2f} \\\\")
 class_rows=[f"{c} ({esc(NAMES[c])}) & {int(r.support)} & {100*r.precision:.2f} & {100*r.recall:.2f} & {100*r.f1:.2f} & {r.auc:.3f} \\\\" for _,r in cc.iterrows() for c in [r.class_label]]
 prop=sm[sm.model=="KineTwin-Former"].iloc[0];base=sm[sm.model==manifest["statistics"]["best_baseline"]].iloc[0];gain=100*(prop.macro_f1_mean-base.macro_f1_mean);n=manifest["dataset"]
 tex=f'''% Auto-generated from a real public-data experiment.\n% Required packages: graphicx, booktabs, multirow, siunitx\n\\section{{Results and Analysis}}\n\\label{{sec:results}}\n\n\\subsection{{Public Dataset and Experimental Protocol}}\nThe external validation used the public UCI Weight Lifting Exercises dataset, specifically the complete \\texttt{{pml-training.csv}} partition. The downloaded file contained {n['raw_samples']:,} time samples from {n['subjects']} participants and was converted into {n['windows']:,} labeled exercise windows. Only the six-axis inertial channels from the upper-arm and forearm units were retained to approximate the proposed proximal--distal dual-IMU configuration. The five labels represented correct execution (A), forward elbow displacement (B), incomplete lifting (C), incomplete lowering (D), and hip/trunk thrust compensation (E).\n\nA strict leave-one-subject-out (LOSO) evaluation was adopted. For every fold, one participant was held out for testing and another participant was used for model selection; no samples from the test participant entered normalization, training, or early stopping. Each window was resampled to {n['sequence_length']} time steps. The experiment used seed {manifest['training']['seed']} and the downloaded dataset was recorded with SHA-256 \\texttt{{{n['sha256'][:16]}...}} for traceability. The benchmark evaluates movement-quality and compensatory-pattern recognition; it does not constitute direct validation of elbow-angle reconstruction, clinical fatigue estimation, or adaptive treatment efficacy.\n\n\\subsection{{Overall Subject-Independent Performance}}\nTable~\\ref{{tab:model_results}} compares KineTwin-Former with single-segment, early-fusion, and physics-guided Extra-Trees baselines. KineTwin-Former achieved an LOSO macro-F1 of {100*prop.macro_f1_mean:.2f}\\% $\\pm$ {100*prop.macro_f1_std:.2f}\\%, balanced accuracy of {100*prop.balanced_accuracy_mean:.2f}\\% $\\pm$ {100*prop.balanced_accuracy_std:.2f}\\%, and macro-AUC of {prop.macro_auc_ovr_mean:.3f} $\\pm$ {prop.macro_auc_ovr_std:.3f}. Relative to the strongest baseline ({esc(short[manifest['statistics']['best_baseline']])}), the proposed model changed macro-F1 by {gain:+.2f} percentage points. A paired Wilcoxon signed-rank comparison across held-out participants produced $p={manifest['statistics']['wilcoxon_p']:.4f}$; this value is reported as exploratory because the dataset contains only {n['subjects']} participants.\n\n\\begin{{table*}}[t]\n\\centering\n\\caption{{Subject-independent LOSO performance on the public UCI benchmark. Values are mean $\\pm$ standard deviation across participants (\\%).}}\n\\label{{tab:model_results}}\n\\resizebox{{\\textwidth}}{{!}}{{%\n\\begin{{tabular}}{{lcccc}}\n\\toprule\nModel & Accuracy & Balanced Accuracy & Macro-F1 & Macro-AUC \\\\n\\midrule\n{chr(10).join(table_rows)}\n\\bottomrule\n\\end{{tabular}}}}\n\\end{{table*}}\n\n\\begin{{figure*}}[t]\n\\centering\n\\includegraphics[width=0.96\\textwidth]{{figures/model_comparison.pdf}}\n\\caption{{Model comparison under participant-independent LOSO validation. Error bars indicate standard deviation across held-out participants rather than random sample splits.}}\n\\label{{fig:model_comparison}}\n\\end{{figure*}}\n\nFigure~\\ref{{fig:subject_generalization}} shows the fold-wise results. The inter-participant spread demonstrates that random sample-level partitions would conceal substantial subject-domain shift. The cross-segment model remained competitive across most participants, but lower-performing folds indicate that personalization and sensor-placement calibration remain important before deployment.\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=\\columnwidth]{{figures/subject_generalization.pdf}}\n\\caption{{Macro-F1 for each held-out participant.}}\n\\label{{fig:subject_generalization}}\n\\end{{figure}}\n\n\\subsection{{Class-Wise Movement-Quality Recognition}}\nThe aggregated class-wise metrics are listed in Table~\\ref{{tab:class_results}}. Figure~\\ref{{fig:confusion}} presents the row-normalized confusion matrix, while Fig.~\\ref{{fig:roc}} presents one-vs-rest ROC curves. These analyses distinguish a general correct/incorrect decision from the harder task of identifying the underlying execution error.\n\n\\begin{{table}}[t]\n\\centering\n\\caption{{Aggregated out-of-subject class-wise performance.}}\n\\label{{tab:class_results}}\n\\resizebox{{\\columnwidth}}{{!}}{{%\n\\begin{{tabular}}{{lccccc}}\n\\toprule\nClass & $N$ & Precision & Recall & F1 & AUC \\\\n\\midrule\n{chr(10).join(class_rows)}\n\\bottomrule\n\\end{{tabular}}}}\n\\end{{table}}\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=0.95\\columnwidth]{{figures/confusion_matrix.pdf}}\n\\caption{{Row-normalized confusion matrix for KineTwin-Former. A denotes correct execution; B--E denote specific execution errors.}}\n\\label{{fig:confusion}}\n\\end{{figure}}\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=0.95\\columnwidth]{{figures/roc_curves.pdf}}\n\\caption{{One-vs-rest ROC analysis using pooled predictions from all held-out participants.}}\n\\label{{fig:roc}}\n\\end{{figure}}\n\n\\subsection{{Hierarchical Rehabilitation Interpretation}}\nThe same out-of-subject predictions were evaluated at three interpretation levels. Five-class quality recognition yielded a macro-F1 of {100*hier['five']['macro_f1']:.2f}\\%. Collapsing classes B--E into an incorrect-execution category increased binary macro-F1 to {100*hier['binary']['macro_f1']:.2f}\\%. Grouping the labels into correct execution, compensatory displacement/thrust (B and E), and incomplete ROM (C and D) yielded a taxonomy-level macro-F1 of {100*hier['taxonomy']['macro_f1']:.2f}\\%. This hierarchy is useful because adaptive rehabilitation may require a reliable safety-level warning even when the exact error type is uncertain.\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=\\columnwidth]{{figures/hierarchical_tasks.pdf}}\n\\caption{{Performance at increasingly coarse rehabilitation interpretation levels.}}\n\\label{{fig:hierarchical}}\n\\end{{figure}}\n\n\\subsection{{Representation, Confidence, and Failure Analysis}}\nThe learned digital-twin embedding in Fig.~\\ref{{fig:embedding}} exhibits structured separation among movement-quality classes, while partial overlap is consistent with gradual biomechanical transitions rather than perfectly discrete behaviors. The reliability diagram in Fig.~\\ref{{fig:reliability}} produced an expected calibration error of {manifest['statistics']['ece']:.3f}. Accordingly, confidence should be used as a gating variable: low-confidence predictions should maintain the current exercise target or request repetition rather than automatically increase difficulty.\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=\\columnwidth]{{figures/embedding_pca.pdf}}\n\\caption{{PCA projection of the held-out KineTwin-Former embeddings. PCA is used only for visualization.}}\n\\label{{fig:embedding}}\n\\end{{figure}}\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=0.92\\columnwidth]{{figures/reliability.pdf}}\n\\caption{{Confidence calibration of pooled LOSO predictions.}}\n\\label{{fig:reliability}}\n\\end{{figure}}\n\nThe cross-segment error landscape in Fig.~\\ref{{fig:error_energy}} relates failures to relative proximal--distal inertial energy. Errors occurring in regions of high relative angular or translational energy may reflect abrupt compensation, sensor-placement variability, or transition segments. This observation supports the proposed uncertainty-aware controller rather than unconditional adaptation after every predicted repetition.\n\n\\begin{{figure}}[t]\n\\centering\n\\includegraphics[width=0.94\\columnwidth]{{figures/error_energy.pdf}}\n\\caption{{Correct and incorrect predictions in the relative inertial-energy space.}}\n\\label{{fig:error_energy}}\n\\end{{figure}}\n\n\\subsection{{Relevance to the M5StickC Plus 2 Prototype}}\nThe benchmark channels match the proposed hardware at the modality level because both use three-axis acceleration and three-axis angular velocity at two upper-limb locations. Nevertheless, the public sensors, attachment geometry, sampling process, exercise protocol, and participant population differ from the M5StickC deployment. Therefore, these results provide external proof-of-concept for dual-segment movement-quality representation and compensatory-pattern recognition, not a device-equivalence claim. Direct validation of personalized elbow ROM requires synchronized M5StickC recordings against a goniometer or optical reference. Fatigue-aware modeling requires exertion or fatigue ground truth, and the adaptive controller requires a prospective safety and usability study.\n\n\\subsection{{Main Finding}}\nUnder strict participant-independent evaluation, the public-data experiment demonstrates that a physics-guided dual-stream temporal representation can extract rehabilitation-relevant information from paired upper-arm and forearm IMU signals. The strongest evidence supports movement-quality classification and compensation-aware feedback. The ROM, fatigue, and closed-loop adaptation modules should remain framed as system capabilities to be validated in the project-specific acquisition phase rather than as clinically established outcomes.\n'''
 (OUT/"Results_and_Analysis.tex").write_text(tex)
 # concise standalone readme
 (OUT/"RESULTS_README.txt").write_text("Generated from real public UCI data under LOSO validation.\nAll figures are vector PDF.\nInsert Results_and_Analysis.tex into the IEEE manuscript and copy figures/.\nDo not claim direct M5StickC ROM/fatigue clinical validation from this benchmark.\n")
 print("Generated Results_and_Analysis.tex and",len(list(FIG.glob("*.pdf"))),"figures")
if __name__=="__main__":main()
